data class OrderedEvent(val customer: String, val item: String)

fun main() {
    val bus = EventBus<OrderedEvent>()
    bus.subscribe { println("stock view got   $it") }
    bus.subscribe { throw IllegalStateException("the sales chart is down") }
    val email = bus.subscribe { println("email sender got $it") }

    bus.publish(OrderedEvent("Ana", "rye bread"))
    email.close()                                                 // unsubscribe
    bus.publish(OrderedEvent("Ben", "jam"))
}

// Closest Java equivalent: the JDK's Flow API, where SubmissionPublisher delivers every event, plus a tiny
// "latest value" holder that drops equal values the way Kotlin's StateFlow does. The JDK has no StateFlow.
package workbench.patterns.l08;

import java.util.List;
import java.util.Objects;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.SubmissionPublisher;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

public class StateVsSharedJava {

    /** Holds one current value and tells observers about changes; equal values are dropped. */
    static final class LatestValue<T> {
        private final List<Consumer<T>> observers = new CopyOnWriteArrayList<>();
        private T value;

        LatestValue(T initial) { value = initial; }

        synchronized void set(T next) {
            if (Objects.equals(value, next)) return;     // StateFlow-style conflation by equals()
            value = next;
            observers.forEach(o -> o.accept(next));
        }

        synchronized void observe(Consumer<T> o) {
            observers.add(o);
            o.accept(value);                             // new observers get the current value first
        }
    }

    public static void main(String[] args) throws Exception {
        LatestValue<String> state = new LatestValue<>("nothing yet");
        List<String> fromState = new CopyOnWriteArrayList<>();
        state.observe(fromState::add);

        List<String> fromEvents = new CopyOnWriteArrayList<>();
        CompletableFuture<Void> done;
        try (SubmissionPublisher<String> events = new SubmissionPublisher<>()) {
            done = events.consume(fromEvents::add);     // a subscriber that gets every item
            for (String update : List.of("rye bread", "rye bread", "jam")) {   // two loaves sold, then a jar of jam
                state.set(update);
                events.submit(update);
            }
        }                                                // close() completes the stream
        done.get(5, TimeUnit.SECONDS);

        System.out.println("state holder saw:    " + fromState);
        System.out.println("event publisher saw: " + fromEvents);
    }
}

sections.body:
Back behind the counter, the spike holds order slips. Each slip says what to do and with what: "restock rye bread, 12 loaves". A slip can wait on the spike, be done now, be crossed out, or be copied and done again. **Command** turns a request into that kind of slip: an object that holds what to do and with which arguments, a value you can keep. Once a request is a value, you can queue it, log it, retry it and undo it.

For a shelf in the shop, a sealed interface of records is the natural shape:

```java
sealed interface Command permits Restock, Sell {
    void apply(Shelf s);
    void undo(Shelf s);
}
record Restock(int units) implements Command {
    public void apply(Shelf s) { s.units += units; }
    public void undo(Shelf s)  { s.units -= units; }
}
record Sell(int units) implements Command {
    public void apply(Shelf s) {
        if (s.units < units) throw new IllegalStateException("not enough on the shelf");
        s.units -= units;
    }
    public void undo(Shelf s)  { s.units += units; }
}

final class CommandLog {
    private final Deque<Command> history = new ArrayDeque<>();
    void run(Command c, Shelf s) { c.apply(s); history.push(c); }       // record only after success
    void undoLast(Shelf s) { Command c = history.poll(); if (c != null) c.undo(s); }
}
```

```kotlin
sealed interface Command {
    fun apply(s: Shelf)
    fun undo(s: Shelf)
}
data class Restock(val units: Int) : Command {
    override fun apply(s: Shelf) { s.units += units }
    override fun undo(s: Shelf) { s.units -= units }
}
data class Sell(val units: Int) : Command {
    override fun apply(s: Shelf) {
        check(s.units >= units) { "not enough on the shelf" }
        s.units -= units
    }
    override fun undo(s: Shelf) { s.units += units }
}

class CommandLog {
    private val history = ArrayDeque<Command>()
    fun run(c: Command, s: Shelf) { c.apply(s); history.addFirst(c) }   // record only after success
    fun undoLast(s: Shelf) { history.removeFirstOrNull()?.undo(s) }
}
```

Two details carry the pattern. First, `run` records the command only after `apply` succeeds. `UndoDemo`, in the Try it, restocks 12 loaves, sells 5, and then tries to sell 40:

```text
rejected: not enough on the shelf
units 7, history [Sell[units=5], Restock[units=12]]
after one undo: units 12, history [Restock[units=12]]
```

Swap the two calls in `run`, so the command is recorded before it's applied, and the rejected sale of 40 sits on top of the history. The next undo puts back 40 loaves that never left, and the shelf shows 47. The baker will want to know where they came from.

Second, the commands are data. `Sell[units=5]` prints well, compares by value, and can be written to a file or a table and read back later.

The slip picture holds up well, and it breaks where the paper ends. Crossing out a slip is easy. Crossing out a sale is only safe while everything stays inside the program; the next section shows why.

**Record a command for undo only after it has succeeded.**

When a command needs no undo and no data, the class disappears. `Runnable`, `Callable` and `() -> Unit` are commands, and `executor.submit(() -> printLabel(orderNo))` hands one to an executor, the JDK's pool of worker threads, which works through its queue. Keep a named class when you need what a lambda can't give: equality, a readable log line, a way to store it, or a second method such as `undo`.

code.src:
package workbench.patterns.l08;

import java.util.ArrayDeque;
import java.util.Deque;

/** Commands as records, an undo log, and the one rule that keeps undo honest. */
public class UndoDemo {
    static final class Shelf { int units; }

    sealed interface Command permits Restock, Sell {
        void apply(Shelf s);
        void undo(Shelf s);
    }

    record Restock(int units) implements Command {
        public void apply(Shelf s) { s.units += units; }
        public void undo(Shelf s) { s.units -= units; }
    }

    record Sell(int units) implements Command {
        public void apply(Shelf s) {
            if (s.units < units) throw new IllegalStateException("not enough on the shelf");
            s.units -= units;
        }
        public void undo(Shelf s) { s.units += units; }
    }

    static final class CommandLog {
        final Deque<Command> history = new ArrayDeque<>();

        void run(Command c, Shelf s) {
            c.apply(s);              // 1. apply first
            history.push(c);         // 2. record only after it worked
        }

        void undoLast(Shelf s) {
            Command c = history.poll();
            if (c != null) c.undo(s);
        }
    }

    public static void main(String[] args) {
        Shelf rye = new Shelf();
        CommandLog log = new CommandLog();
        log.run(new Restock(12), rye);
        log.run(new Sell(5), rye);
        try {
            log.run(new Sell(40), rye);
        } catch (IllegalStateException e) {
            System.out.println("rejected: " + e.getMessage());
        }
        System.out.println("units " + rye.units + ", history " + log.history);
        log.undoLast(rye);
        System.out.println("after one undo: units " + rye.units + ", history " + log.history);
    }
}

